examples:
// Reference copy vs. content copy
int[] a = {1, 2, 3};
int[] b = a;        // b points to same array!
b[0] = 99;
System.out.println(a[0]);  // 99 (changed!)

// Deep copy with loop
int[] c = new int[a.length];
for (int i = 0; i < a.length; i++)
    c[i] = a[i];

// Or use System.arraycopy
System.arraycopy(a, 0, c, 0, a.length);
